import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const whiteDragonScenarios=['white-sword-ordinary','white-sword-first','white-sword-inherited','white-sword-full','white-slash-ordinary','white-slash-first','white-slash-inherited','white-slash-full'] as const;
export type WhiteDragonScenario=typeof whiteDragonScenarios[number];
export function isWhiteDragonScenario(name:string):name is WhiteDragonScenario{return (whiteDragonScenarios as readonly string[]).includes(name);}
export function whiteDragonMode(name:WhiteDragonScenario){const slash=name.startsWith('white-slash'),full=name.endsWith('full'),inherited=name.endsWith('inherited'),dedicated=!name.endsWith('ordinary');return {card:slash?'a2-p11-r2c2':'a2-p11-r2c1',owner:full||inherited?'聖騎士ランスロット2':'聖騎士ランスロット',dedicated,variant:dedicated?(full?'lancelot-2' as const:'lancelot-1' as const):null,chant:slash&&!full,damage:slash?(full?25:dedicated?15:10):(full?15:dedicated?10:6),use:slash?7:6,effect:slash?(full?9:dedicated?8:7):(full?8:dedicated?7:6)};}
/** Preparation uses actual CHANT/full turns or a distinct physical APPROACH, never direct zone/distance injection. */
export function makeWhiteDragonScenario(name:WhiteDragonScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;prepared?:boolean;follower?:string}={}){
 const m=whiteDragonMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??m.owner);assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.warrior_level=20+(options.level??m.use)-stats.warrior_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;
 const card=takeCard(s,a,m.card),advance=takeCard(s,a,'a2-p24-r1c2'),first=takeCard(s,b,'a2-p07-r1c1'),second=takeCard(s,b,'a2-p07-r1c2'),fate=takeCard(s,c,'命運凶変'),guard=options.follower?takeCard(s,b,options.follower):null;for(const id of [a,b,c,d])trimHand(s,id,card,advance,first,second,fate,...(guard?[guard]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`WHITE_DRAGON_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WHITE_DRAGON_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WHITE_DRAGON_IDS');}
 for(const id of [a,b,c,d]){if(guard&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(options.prepared===false)return s;
 if(m.chant){act(a,{type:'CHANT',cardInstanceId:card});for(let n=0;n<100;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==card).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('WHITE_DRAGON_TURN');}}
 else if(name.startsWith('white-sword')){act(a,{type:'APPROACH',targetId:b,cardInstanceId:advance});for(let n=0;n<100&&s.windows?.length;n++){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}}return s;
}
